<script setup>
import { computed, ref, onMounted, onBeforeUnmount, nextTick } from 'vue'
import { ArrowUpRight, ArrowRight, Plus, Search, SlidersHorizontal, LayoutDashboard, BriefcaseBusiness, CalendarDays, Settings2, Leaf, Sun, Moon, ChevronDown, X, MapPin, Banknote, MoreHorizontal, Check, ShieldCheck, Download, Upload, Trash2, Star, GripVertical, ExternalLink, Minimize2, Maximize2, Printer, FileText, ArrowLeft, Eye, EyeOff } from 'lucide-vue-next'
import CardPreferences from './CardPreferences.vue'
import { useApplications } from './store'
import { applicationsCsv } from './export.js'
import { stages, boardStages, endingOutcomes, columnForStage, employmentTypes, reasonLabels, blankApplication, validateApplications, ageLabel, isApplicationUrl } from './data'
const store = useApplications()
const search = ref(''), workplace = ref('All locations'), view = ref('pipeline'), filterOpen = ref(false), theme = ref('light'), modal = ref(false), draft = ref(blankApplication()), tab = ref('details'), customPerk = ref(''), notice = ref(''), importInput = ref(null), companyInput = ref(null), dragging = ref(''), dropStage = ref(''), boardDensity = ref('comfortable'), minimizedColumns = ref(new Set())
const printLog = ref(null), workSearchName = ref(''), workSearchSsn = ref(''), workSearchStart = ref(new Date().toISOString().slice(0, 10)), workSearchWeeks = ref(1), workSearchRequired = ref(3), privacyBlur = ref(false)
const pipelineStage = computed({ get: () => columnForStage(draft.value.stage), set: value => { draft.value.stage = value } })
const now = ref(Date.now())
let ageTimer
const age = timestamp => ageLabel(timestamp, now.value)
const timestampLabel = timestamp => timestamp ? new Date(timestamp).toLocaleString() : 'Not recorded'
const oldestInStage = stage => { const items = filtered.value.filter(a => columnForStage(a.stage) === stage); const dates = items.map(a => a.stageEnteredAt).filter(Boolean).sort(); return dates.length ? `Oldest ${age(dates[0])}` : items.length ? 'Age unknown' : 'No items' }
let noticeTimer, previousFocus
try { theme.value = localStorage.getItem('pipedin.theme') || (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light') } catch {}
try {
  const boardPreferences = JSON.parse(localStorage.getItem('pipedin.board.v1') || '{}')
  boardDensity.value = boardPreferences.density === 'condensed' ? 'condensed' : 'comfortable'
  minimizedColumns.value = new Set(Array.isArray(boardPreferences.minimized) ? boardPreferences.minimized : [])
} catch {}
function saveBoardPreferences() { try { localStorage.setItem('pipedin.board.v1', JSON.stringify({ density: boardDensity.value, minimized: [...minimizedColumns.value] })) } catch {} }
function setBoardDensity(density) { boardDensity.value = density; saveBoardPreferences() }
function toggleColumnMinimized(stage) { const next = new Set(minimizedColumns.value); next.has(stage) ? next.delete(stage) : next.add(stage); minimizedColumns.value = next; saveBoardPreferences() }
function applyTheme() { document.documentElement.dataset.theme = theme.value }
applyTheme()
function toggleTheme() { theme.value = theme.value === 'light' ? 'dark' : 'light'; applyTheme(); try { localStorage.setItem('pipedin.theme', theme.value) } catch { toast('Theme changed for this session. Browser storage is unavailable.') } }
const filtered = computed(() => store.applications.filter(a => `${a.company} ${a.title} ${a.business} ${a.location}`.toLowerCase().includes(search.value.toLowerCase()) && (workplace.value === 'All locations' || a.workplace === workplace.value)))
const active = computed(() => store.applications.filter(a => ['applied','reached','interviews','offer'].includes(a.stage)).length)
const interviewCount = computed(() => store.applications.filter(a => a.stage === 'interviews').length)
const offerCount = computed(() => store.applications.filter(a => ['offer','accepted'].includes(a.stage)).length)
const responseRate = computed(() => store.applications.some(a => a.stage !== 'potential') ? Math.round(store.applications.filter(a => ['reached','interviews','offer','accepted','declined','rejected'].includes(a.stage)).length / store.applications.filter(a => a.stage !== 'potential').length * 100) : 0)
const interviewEvents = computed(() => filtered.value.flatMap(a => a.interviews.map(i => ({ ...i, application: a }))).sort((a,b) => (a.date || '9999').localeCompare(b.date || '9999')))
const dateLabel = value => value ? new Date(value + 'T12:00:00').toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) : 'Not scheduled'
function toast(message) { notice.value = message; clearTimeout(noticeTimer); noticeTimer = setTimeout(() => notice.value = '', 4500) }
async function openApplication(item, stage = 'applied') { previousFocus = document.activeElement; draft.value = item ? JSON.parse(JSON.stringify(item)) : { ...blankApplication(), stage }; tab.value = 'details'; customPerk.value = ''; modal.value = true; await nextTick(); companyInput.value?.focus() }
function closeModal() { modal.value = false; previousFocus?.focus() }
function save() { if (!stages.some(stage => stage.id === draft.value.stage)) { tab.value = 'details'; toast('Choose a reason for ending.'); return }; if (!draft.value.company.trim() || (draft.value.stage !== 'potential' && !draft.value.title.trim())) { tab.value = 'details'; return }; if (draft.value.stage === 'potential' && !isApplicationUrl(draft.value.url)) { tab.value = 'details'; toast('Enter a valid http or https application link.'); return }; if (store.save(JSON.parse(JSON.stringify(draft.value)))) { closeModal(); toast('Application saved. Your next chapter is taking shape.'); } }
function updateCard(application, changes) { if (!store.save({ ...JSON.parse(JSON.stringify(application)), ...changes })) toast(store.error) }
function remove() { if (confirm(`Delete your application to ${draft.value.company}? This cannot be undone.`) && store.remove(draft.value.id)) { closeModal(); toast('Application deleted.') } }
function addRound() { draft.value.interviews.push({ id: crypto.randomUUID(), name: '', person: '', date: '', rating: 0, notes: '' }) }
function clearApplications() { if (confirm('Delete all applications from this browser? This cannot be undone.') && store.replace([])) toast('All applications removed.') }
function addPerk() { const perk = customPerk.value.trim(); if (perk && !draft.value.perks.includes(perk)) draft.value.perks.push(perk); customPerk.value = '' }
function drop(stage) {
  const item = store.applications.find(a => a.id === dragging.value)
  if (item && columnForStage(item.stage) !== stage) {
    if (stage === 'ended' || (stage !== 'potential' && !item.title.trim()) || (stage === 'potential' && !isApplicationUrl(item.url))) openApplication({ ...JSON.parse(JSON.stringify(item)), stage })
    else if (store.move(item.id, stage)) toast(`Moved to ${stages.find(s => s.id === stage).name}.`)
  }
  dragging.value = ''; dropStage.value = ''
}
function downloadFile(content, type, filename) {
  const url = URL.createObjectURL(new Blob([content], { type }))
  const a = document.createElement('a'); a.href = url; a.download = filename
  document.body.append(a); a.click(); a.remove()
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}
function exportData() {
  downloadFile(JSON.stringify({ version: 1, applications: store.applications }, null, 2), 'application/json', `pipedIn-backup-${new Date().toISOString().slice(0,10)}.json`)
  toast('JSON backup downloaded with all applications and history.')
}
function exportCsv() {
  downloadFile(applicationsCsv(store.applications), 'text/csv;charset=utf-8', `pipedIn-applications-${new Date().toISOString().slice(0,10)}.csv`)
  toast(`CSV downloaded with ${store.applications.length} applications and their current status.`)
}
function makeWorkSearchRow() { return { date: '', activity: '', employer: '', address: '', cityStateZip: '', phone: '', person: '', mail: '', email: '', fax: '', contactOther: '', hired: false, notHiring: false, startDate: '', applicationFiled: false, resultOther: '' } }
function workSearchRowFromApplication(application) { return { ...makeWorkSearchRow(), date: application.date, activity: `Applied for job: ${application.title || 'Application'}`, employer: application.company, cityStateZip: application.location, contactOther: application.url, applicationFiled: true, resultOther: stages.find(stage => stage.id === application.stage)?.name || '' } }
function addDays(date, days) { const next = new Date(`${date}T12:00:00`); next.setDate(next.getDate() + days); return next.toISOString().slice(0, 10) }
function shortDate(date) { return new Date(`${date}T12:00:00`).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }) }
function escapeHtml(value) { return String(value ?? '').replace(/[&<>'"]/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[character]) }
function workSearchInput(value, type = 'text', placeholder = '') { return `<input type="${type}" value="${escapeHtml(value)}"${placeholder ? ` placeholder="${escapeHtml(placeholder)}"` : ''}>` }
function workSearchRowsHtml(rows) { return rows.map(row => `<tr><td><span>Date of Activity</span>${workSearchInput(row.date, 'date')}<span>Work Search Activity</span><textarea>${escapeHtml(row.activity)}</textarea><span>Type of Job</span>${workSearchInput('')}</td><td><span>Name</span>${workSearchInput(row.employer)}<span>Address</span>${workSearchInput(row.address)}<span>City, State, Zip Code</span>${workSearchInput(row.cityStateZip)}<span>Area Code + Phone #</span>${workSearchInput(row.phone)}</td><td><span>Person Contacted</span>${workSearchInput(row.person)}<span>By Mail</span>${workSearchInput(row.mail)}<span>Email</span>${workSearchInput(row.email)}<span>Fax #</span>${workSearchInput(row.fax)}${workSearchInput(row.contactOther, 'text', 'Other')}</td><td><label><input type="checkbox"${row.hired ? ' checked' : ''}> Hired</label><label><input type="checkbox"${row.notHiring ? ' checked' : ''}> Not hiring</label><span>Start date</span>${workSearchInput(row.startDate, 'date')}<label><input type="checkbox"${row.applicationFiled ? ' checked' : ''}> Application filed</label>${workSearchInput(row.resultOther, 'text', 'Other')}</td></tr>`).join('') }
function workSearchPageHtml(week, index, total, log) { return `<article class="work-search-page"><h1>The Texas Workforce Commission Work Search Activity Log</h1><div class="work-search-meta"><label>Name:${workSearchInput(log.name)}</label><label>Week of:${workSearchInput(shortDate(week.start), 'text')}</label><label>to${workSearchInput(shortDate(addDays(week.start, 6)), 'text')}</label><label>Social Security #:${workSearchInput(log.ssn)}</label><label>Number of Required Searches:${workSearchInput(log.required, 'number')}</label></div><p class="work-search-note">If you are still unemployed after eight weeks of benefits, you should reduce your salary requirement and look at more job openings.</p><table><thead><tr><th>Date, Description of Work Search</th><th>Name, Location and Telephone Number of Employer/Service/Agency</th><th>Contact Information</th><th>Results</th></tr></thead><tbody>${workSearchRowsHtml(week.rows)}</tbody></table><footer>Keep this form for your records. Submit a copy to TWC only if requested.</footer><small>BN900E (10-12-23) · Week ${index + 1} of ${total}</small></article>` }
function openWorkSearchTab(log) {
  const tab = window.open('', '_blank')
  if (!tab) { toast('Allow pop-ups to open the printable log in a new tab.'); return }
  const pages = log.weeks.map((week, index) => workSearchPageHtml(week, index, log.weeks.length, log)).join('')
  const styles = [...document.styleSheets].flatMap(sheet => { try { return [...sheet.cssRules].map(rule => rule.cssText) } catch { return [] } }).join('\n')
  tab.document.write(`<!doctype html><html><head><meta charset="UTF-8"><title>Work Search Activity Log</title><style>${styles}</style></head><body><div class="app-shell"><main><div class="work-search-print-view"><div class="print-toolbar"><button class="secondary" id="back">Close</button><button class="secondary" id="blur">Blur company names</button><button class="primary" id="print">Print / save PDF</button></div>${pages}</div></main></div></body></html>`)
  tab.document.close()
  tab.document.getElementById('print').addEventListener('click', () => tab.print())
  tab.document.getElementById('back').addEventListener('click', () => tab.close())
  tab.document.getElementById('blur').addEventListener('click', event => { tab.document.body.classList.toggle('privacy-blur'); event.currentTarget.textContent = tab.document.body.classList.contains('privacy-blur') ? 'Show company names' : 'Blur company names' })
}
function generateWorkSearchLog() {
  const weeks = Math.min(52, Math.max(1, Number(workSearchWeeks.value) || 1))
  workSearchWeeks.value = weeks
  const log = { name: workSearchName.value, ssn: workSearchSsn.value, required: workSearchRequired.value, weeks: Array.from({ length: weeks }, (_, index) => { const start = addDays(workSearchStart.value, index * 7); const end = addDays(start, 6); const applications = store.applications.filter(application => application.date >= start && application.date <= end).sort((a, b) => a.date.localeCompare(b.date)).slice(0, 5); return { start, rows: [...applications.map(workSearchRowFromApplication), ...Array.from({ length: 5 - applications.length }, makeWorkSearchRow)] } }) }
  printLog.value = structuredClone(log)
  openWorkSearchTab(log)
}
function closeWorkSearchLog() { printLog.value = null }
function printWorkSearchLog() { window.print() }
function togglePrivacyBlur() { privacyBlur.value = !privacyBlur.value }
async function importData(event) { const file = event.target.files[0]; if (!file) return; try { if (file.size > 10000000) throw new Error('Please choose a backup smaller than 10 MB.'); const parsed = JSON.parse(await file.text()); if (parsed.version !== 1) throw new Error('Unsupported backup version.'); const next = validateApplications(parsed.applications); if (!store.applications.length || confirm(`Replace your ${store.applications.length} applications with ${next.length} applications from this backup? Export a backup first if needed.`)) { if (store.replace(next)) toast('Backup restored.') } } catch (error) { toast(error.message || 'Unable to import this file.') } event.target.value = '' }
function safeUrl(value) { try { const url = new URL(value); return ['https:', 'http:'].includes(url.protocol) ? url.href : null } catch { return null } }
function keydown(event) { if (!modal.value) return; if (event.key === 'Escape') closeModal(); if (event.key === 'Tab') { const elements = [...document.querySelectorAll('.dialog button, .dialog input, .dialog select, .dialog textarea, .dialog a[href]')].filter(el => !el.disabled && el.getClientRects().length); const first = elements[0], last = elements.at(-1); if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus() } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus() } } }
onMounted(() => { document.addEventListener('keydown', keydown); ageTimer = setInterval(() => now.value = Date.now(), 30000) })
onBeforeUnmount(() => { document.removeEventListener('keydown', keydown); clearTimeout(noticeTimer); clearInterval(ageTimer) })
</script>

<template>
  <div class="app-shell" :class="{ 'privacy-blur': privacyBlur }"><input ref="importInput" type="file" accept="application/json,.json" aria-label="Import JSON backup file" hidden @change="importData">
    <aside class="sidebar">
      <a class="brand" aria-label="pipedIn home" href="#" @click.prevent="view = 'pipeline'"><picture><source media="(max-width: 850px)" srcset="/square-logo.webp"><img class="brand-mark" src="/full-logo.webp" width="144" height="48" alt="pipedIn"></picture></a>
      <div class="workspace"><span class="avatar">Y</span><div><strong>Your workspace</strong><small>Personal job search</small></div><ChevronDown :size="15" /></div>
      <div class="nav-label">WORKSPACE</div>
      <nav aria-label="Main navigation">
        <button :class="{ selected: view === 'pipeline' }" @click="view = 'pipeline'"><LayoutDashboard :size="18" /> My pipeline <span class="nav-count">{{ store.applications.length }}</span></button>
        <button :class="{ selected: view === 'applications' }" @click="view = 'applications'"><BriefcaseBusiness :size="18" /> All applications</button>
        <button :class="{ selected: view === 'interviews' }" @click="view = 'interviews'"><CalendarDays :size="18" /> Interviews <span v-if="interviewEvents.length" class="tiny-dot"></span></button>
        <button :class="{ selected: view === 'reports' }" @click="view = 'reports'"><FileText :size="18" /> Export Logs</button>
      </nav>
      <div class="sidebar-bottom">
        <div class="encouragement"><span class="plant">✳</span><strong>A little progress, every day.</strong><p>Your next chapter starts with<br>one application.</p><div class="mini-line"></div></div>
        <button class="sidebar-setting" @click="view = 'settings'"><Settings2 :size="18" /> Settings & data</button>
        <div class="sidebar-footer"><span><i class="online-dot"></i> Stored on this device</span><button class="icon-button" :aria-label="privacyBlur ? 'Show company names' : 'Blur company names'" :aria-pressed="privacyBlur" @click="togglePrivacyBlur"><EyeOff v-if="privacyBlur" :size="17" /><Eye v-else :size="17" /></button><button class="icon-button" @click="toggleTheme" :aria-label="theme === 'light' ? 'Switch to dark mode' : 'Switch to light mode'"><Moon v-if="theme === 'light'" :size="17" /><Sun v-else :size="17" /></button></div>
      </div>
    </aside>

    <main>
      <div class="main-container">
      <section class="page-content">
        <div class="page-heading"><div><div class="eyebrow">A LITTLE MOMENTUM GOES A LONG WAY</div><h1>{{ view === 'pipeline' ? 'Your next chapter, in motion.' : view === 'applications' ? 'Every opportunity, in one place.' : view === 'interviews' ? 'Make a great connection.' : view === 'reports' ? 'Keep your search records ready.' : 'Your workspace. Your data.' }}</h1><p> {{ view === 'settings' ? 'A private space, with you in control.' : view === 'reports' ? 'Generate a weekly work search activity log from your applications.' : 'Keep your opportunities organized. Make room for what’s next.' }}</p></div><button v-if="view !== 'settings' && view !== 'reports'" class="primary" @click="openApplication()"><Plus :size="17" /> Add application</button></div>

        <div v-if="store.error" class="error-banner" role="alert">{{ store.error }}</div>
        <template v-if="view !== 'settings' && view !== 'reports'">
          <div class="stats-grid">
            <div class="stat"><span class="stat-icon mint"><BriefcaseBusiness :size="19" /></span><div><span class="stat-label">Active applications</span><div class="stat-value">{{ active }} <span class="stat-note">opportunities ahead</span></div></div><svg class="sparkline" viewBox="0 0 70 30"><path d="M1 25L13 21L25 23L37 13L49 16L61 5L69 7" /></svg></div>
            <div class="stat"><span class="stat-icon sand"><CalendarDays :size="19" /></span><div><span class="stat-label">In interviews</span><div class="stat-value">{{ interviewCount }} <span class="stat-note">conversations started</span></div></div></div>
            <div class="stat"><span class="stat-icon sage"><Star :size="19" /></span><div><span class="stat-label">Offers received</span><div class="stat-value">{{ offerCount }} <span class="stat-note">reasons to celebrate</span></div></div></div>
            <div class="stat"><span class="stat-icon blue"><ArrowUpRight :size="21" /></span><div><span class="stat-label">Response rate</span><div class="stat-value">{{ responseRate }}<small>%</small><span class="stat-note">of all applications</span></div></div></div>
          </div>

          <div class="board-toolbar"><div class="board-tabs"><button class="active"><LayoutDashboard :size="16" /> {{ view === 'pipeline' ? 'Pipeline view' : view === 'applications' ? 'All applications' : 'Interview rounds' }}</button><span class="total-label">{{ filtered.length }} applications</span></div><div class="toolbar-actions"><div v-if="view === 'pipeline'" class="view-toggle" role="group" aria-label="Board card density"><button :class="{ active: boardDensity === 'comfortable' }" aria-label="Full card view" :aria-pressed="boardDensity === 'comfortable'" @click="setBoardDensity('comfortable')">Full view</button><button :class="{ active: boardDensity === 'condensed' }" aria-label="Condensed card view" :aria-pressed="boardDensity === 'condensed'" @click="setBoardDensity('condensed')">Condensed</button></div><label class="search"><Search :size="16" /><input v-model="search" placeholder="Search applications…" aria-label="Search applications"><span>/</span></label><button class="filter-button" :class="{ 'filter-active': workplace !== 'All locations' }" @click="filterOpen = !filterOpen"><SlidersHorizontal :size="15" /> Filters<span v-if="workplace !== 'All locations'" class="tiny-dot"></span></button></div></div>
          <div class="data-actions" aria-label="Import and export applications"><span>All applications · {{ store.applications.length }}</span><button class="secondary" @click="importInput.click()"><Upload :size="14" /> Import JSON</button><button class="secondary" @click="exportData"><Download :size="14" /> Export JSON</button><button class="secondary" @click="exportCsv"><Download :size="14" /> Export CSV</button></div>
          <div v-if="filterOpen" class="filter-row"><label>Work arrangement <select v-model="workplace"><option>All locations</option><option>Remote</option><option>Hybrid</option><option>Onsite</option></select></label><button class="text-button" @click="workplace = 'All locations'; search = ''">Reset filters</button></div>

          <div v-if="!store.applications.length && !store.error" class="welcome"><div class="welcome-icon"><Leaf :size="25" /></div><div><strong>A fresh start looks good on you.</strong><p>Add your first opportunity, or explore a sample pipeline to see how it works.</p></div><button class="secondary" @click="store.demo(); toast('Sample applications added. You can clear them in Settings & data.')">Explore sample pipeline <ArrowRight :size="15" /></button></div>

          <div v-if="view === 'pipeline'" class="board" aria-label="Application pipeline">
            <section v-for="stage in boardStages" :key="stage.id" class="column" :class="{ 'drop-target': dropStage === stage.id, minimized: minimizedColumns.has(stage.id), condensed: boardDensity === 'condensed' }" @dragover.prevent="dropStage = stage.id" @dragleave.self="dropStage = ''" @drop.prevent="drop(stage.id)">
              <div class="column-heading"><div><span class="stage-dot" :style="{ background: stage.color }"></span><h2>{{ stage.name }}</h2><span class="minimized-column-letter" aria-hidden="true">{{ stage.name.slice(0, 1).toUpperCase() }}</span><span class="stage-count">{{ filtered.filter(a => columnForStage(a.stage) === stage.id).length }}</span></div><div class="column-actions"><button class="icon-button" :aria-label="`${minimizedColumns.has(stage.id) ? 'Expand' : 'Minimize'} ${stage.name}`" @click="toggleColumnMinimized(stage.id)"><Maximize2 v-if="minimizedColumns.has(stage.id)" :size="15" /><Minimize2 v-else :size="15" /></button><button class="icon-button" :aria-label="`Add application to ${stage.name}`" @click="openApplication(null, stage.id)"><Plus :size="16" /></button></div></div>
              <div class="stage-age"><span class="age-badge">{{ oldestInStage(stage.id) }}</span></div><div class="column-line" :style="{ background: stage.color }"></div>
              <div class="cards"><article v-for="application in filtered.filter(a => columnForStage(a.stage) === stage.id)" :key="application.id" class="application-card" :data-color="application.color" draggable="true" @dragstart="dragging = application.id; $event.dataTransfer.setData('text/plain', application.id); $event.dataTransfer.effectAllowed = 'move'" @dragend="dragging = ''; dropStage = ''">
                <button class="condensed-card-main" :aria-label="`${application.company}, ${application.title || 'Saved opportunity'}`" :title="application.company" @click="openApplication(application)"><span class="condensed-card-name">{{ application.company }}</span><span class="condensed-card-position">{{ application.title || 'Saved opportunity' }}</span><span class="minimized-card-letter">{{ application.company.slice(0, 1).toUpperCase() }}</span></button>
                <CardPreferences :color="application.color" :starred="application.starred" :company="application.company" @change="updateCard(application, $event)" />
                <button class="card-main" @click="openApplication(application)"><div class="company-row"><span class="company-logo" :class="`logo-${application.company.toLowerCase().replace(/[^a-z]/g, '')}`">{{ application.company.slice(0,1).toUpperCase() }}</span><div class="company-info"><strong>{{ application.company }}</strong><span>{{ application.business || 'Business not specified' }}</span></div><MoreHorizontal :size="17" class="card-more" /></div><div v-if="columnForStage(application.stage) === 'ended'" class="ending-summary"><span class="ending-badge" :class="application.stage">{{ endingOutcomes.find(outcome => outcome.id === application.stage)?.name }}</span><p v-if="application.reasons[application.stage]">{{ application.reasons[application.stage] }}</p></div><h3>{{ application.title || 'Saved opportunity' }}</h3><div v-if="application.employmentType" class="tags"><span class="perk-tag">{{ application.employmentType }}</span></div><template v-if="application.stage !== 'potential'"><div class="card-location"><MapPin :size="13" />{{ application.location || 'Location not specified' }}</div><div class="salary"><Banknote :size="14" />{{ application.salary || 'Salary not specified' }}</div><div class="tags"><span class="workplace" :class="application.workplace.toLowerCase()"><span class="tag-dot"></span>{{ application.workplace }}</span><span v-for="perk in application.perks.slice(0,2)" :key="perk" class="perk-tag">{{ perk }}</span><span v-if="application.perks.length > 2" class="perk-tag">+{{ application.perks.length - 2 }}</span></div></template><div v-if="application.stage === 'interviews' && application.interviews.length" class="interview-preview"><CalendarDays :size="13" /><span>{{ application.interviews.at(-1).name || 'Interview' }}</span><span class="round-count">{{ application.interviews.length }} round{{ application.interviews.length > 1 ? 's' : '' }}</span></div><div v-if="application.stage === 'offer'" class="offer-message"><span>✧</span> A new door is opening</div></button>
                <div class="card-age"><span class="age-badge" :title="'Entered stage: ' + timestampLabel(application.stageEnteredAt)">{{ age(application.stageEnteredAt) }}<template v-if="application.stageEnteredAt"> in stage</template></span><span :title="timestampLabel(application.createdAt)">{{ application.createdAt ? age(application.createdAt) + ' old' : 'Created date unknown' }}</span></div><a v-if="safeUrl(application.url)" class="application-link" :href="safeUrl(application.url)" target="_blank" rel="noopener noreferrer"><ExternalLink :size="12" /> Open application</a><div class="card-footer"><span :title="timestampLabel(application.updatedAt)">Updated {{ application.updatedAt ? age(application.updatedAt) + ' ago' : 'date unknown' }}</span><button class="icon-button" :aria-label="`Edit or move ${application.company}`" @click="openApplication(application)"><ArrowUpRight :size="14" /></button></div>
              </article>
              <button class="add-card" @click="openApplication(null, stage.id)"><Plus :size="15" /> Add application</button></div>
            </section>
          </div>
          <div v-else-if="view === 'applications'" class="list-view"><div v-if="!filtered.length" class="empty-state">No applications to show. Add an opportunity or adjust your filters.</div><button v-for="a in filtered" :key="a.id" class="list-row" :data-color="a.color" @click="openApplication(a)"><span class="company-logo">{{ a.company[0] }}</span><span><strong><Star v-if="a.starred" class="list-star" :size="14" aria-label="Starred application" />{{ a.company }}</strong><small>{{ a.title || 'Saved opportunity' }}<template v-if="a.employmentType"> · {{ a.employmentType }}</template></small></span><span class="list-location">{{ a.workplace }} · {{ a.location }}</span><span class="age-badge" :title="timestampLabel(a.stageEnteredAt)">{{ age(a.stageEnteredAt) }}<template v-if="a.stageEnteredAt"> in stage</template></span><span class="status-pill">{{ columnForStage(a.stage) === 'ended' ? 'Ended · ' + endingOutcomes.find(o => o.id === a.stage)?.name : stages.find(s => s.id === a.stage).name }}</span><ArrowUpRight :size="17" /></button></div>
          <div v-else class="list-view"><div v-if="!interviewEvents.length" class="empty-state"><CalendarDays :size="30" /><h3>Your next conversation starts here.</h3><p>Open an application and add a round in the Interviews tab.</p></div><button v-for="i in interviewEvents" :key="i.application.id + i.id" class="list-row" @click="openApplication(i.application); tab = 'interviews'"><span class="stat-icon sand"><CalendarDays :size="20" /></span><span><strong>{{ i.name || 'Interview' }} · {{ i.application.company }}</strong><small>{{ i.person || 'Interviewer not specified' }}</small></span><span class="list-location">{{ dateLabel(i.date) }}</span><span class="rating-label">{{ i.rating ? '★'.repeat(i.rating) : 'Not rated' }}</span><ArrowUpRight :size="17" /></button></div>
          <footer class="board-footer"><span><ShieldCheck :size="14" /> Your journey stays yours. All data is saved in this browser.</span><span v-if="view === 'pipeline'"><GripVertical :size="14" /> Drag cards to move them between stages</span><span class="policy-links"><a href="/privacy/">Privacy Policy</a><a href="/terms/">Terms of Service</a></span></footer>
        </template>

        <div v-else-if="view === 'settings'" class="settings-grid"><section class="settings-card"><ShieldCheck :size="27" /><h2>Local by design</h2><p>Your applications are stored in localStorage on this browser. There is no account, server database, or automatic sync. Clearing browser data removes your applications, so keep a backup.</p><button class="secondary" @click="exportData"><Download :size="16" /> Export JSON backup</button><button class="secondary" @click="importInput.click()"><Upload :size="16" /> Import JSON backup</button><button class="secondary" @click="exportCsv"><Download :size="16" /> Export CSV</button><p>JSON keeps every detail for restoring your workspace. CSV lists all applications with their current status, links, and timestamps. Imports replace your applications after confirmation.</p></section><section class="settings-card"><Sun :size="27" /><h2>A calmer workspace</h2><p>Choose the light or dark purple palette. Your preference is saved on this device.</p><button class="secondary" @click="toggleTheme"><Moon v-if="theme === 'light'" :size="16" /><Sun v-else :size="16" /> Switch to {{ theme === 'light' ? 'dark' : 'light' }} mode</button></section><section class="settings-card"><Trash2 :size="25" /><h2>Start fresh</h2><p>Remove all applications from this browser, including any sample data. Export a backup first if you want to keep a copy.</p><button class="danger-button" @click="clearApplications()">Delete all applications</button></section></div>
      </section>
      </div>
      <section v-if="view === 'reports'" class="work-search-generator"><FileText :size="27" /><h2>Work search activity log</h2><p>Make a printable Texas Workforce Commission-style log with one page for each week. Choose up to 52 weeks, fill in the rows, then print or save it as a PDF.</p><div class="work-search-form"><label>Name<input v-model="workSearchName" placeholder="Your name"></label><label>Social Security #<input v-model="workSearchSsn" inputmode="numeric" placeholder="XXX-XX-XXXX"></label><label>Week starting<input v-model="workSearchStart" type="date"></label><label>Weeks<input v-model.number="workSearchWeeks" type="number" min="1" max="52"></label><label>Required searches<input v-model.number="workSearchRequired" type="number" min="0" max="99"></label></div><button class="primary" @click="generateWorkSearchLog"><FileText :size="16" /> Create printable log</button></section>
      <section v-if="printLog" class="work-search-print-view">
        <div class="print-toolbar"><button class="secondary" @click="closeWorkSearchLog"><ArrowLeft :size="16" /> Back to settings</button><button class="primary" @click="printWorkSearchLog"><Printer :size="16" /> Print / save PDF</button></div>
        <article v-for="(week, weekIndex) in printLog.weeks" :key="weekIndex" class="work-search-page">
          <h1>The Texas Workforce Commission Work Search Activity Log</h1>
          <div class="work-search-meta"><label>Name:<input v-model="printLog.name"></label><label>Week of:<input :value="shortDate(week.start)" readonly></label><label>to<input :value="shortDate(addDays(week.start, 6))" readonly></label><label>Social Security #:<input v-model="printLog.ssn"></label><label>Number of Required Searches:<input v-model="printLog.required" type="number"></label></div>
          <p class="work-search-note">If you are still unemployed after eight weeks of benefits, you should reduce your salary requirement and look at more job openings.</p>
          <table><thead><tr><th>Date, Description of Work Search</th><th>Name, Location and Telephone Number of Employer/Service/Agency</th><th>Contact Information</th><th>Results</th></tr></thead><tbody>
            <tr v-for="row in week.rows" :key="row">
              <td><span>Date of Activity</span><input v-model="row.date" type="date"><span>Work Search Activity</span><textarea v-model="row.activity"></textarea><span>Type of Job</span><input></td>
              <td><span>Name</span><input v-model="row.employer"><span>Address</span><input v-model="row.address"><span>City, State, Zip Code</span><input v-model="row.cityStateZip"><span>Area Code + Phone #</span><input v-model="row.phone"></td>
              <td><span>Person Contacted</span><input v-model="row.person"><span>By Mail</span><input v-model="row.mail"><span>Email</span><input v-model="row.email"><span>Fax #</span><input v-model="row.fax"><input v-model="row.contactOther" placeholder="Other"></td>
              <td><label><input v-model="row.hired" type="checkbox"> Hired</label><label><input v-model="row.notHiring" type="checkbox"> Not hiring</label><span>Start date</span><input v-model="row.startDate" type="date"><label><input v-model="row.applicationFiled" type="checkbox"> Application filed</label><input v-model="row.resultOther" placeholder="Other"></td>
            </tr>
          </tbody></table>
          <footer>Keep this form for your records. Submit a copy to TWC only if requested.</footer><small>BN900E (10-12-23) · Week {{ weekIndex + 1 }} of {{ printLog.weeks.length }}</small>
        </article>
      </section>
    </main>

    <div v-if="modal" class="modal-backdrop" @mousedown.self="closeModal"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-header"><div><span class="eyebrow">YOUR NEXT OPPORTUNITY</span><h2 id="dialog-title">{{ store.applications.some(a => a.id === draft.id) ? 'Application details' : draft.stage === 'potential' ? 'Add a potential application' : 'Add an application' }}</h2></div><button class="icon-button" aria-label="Close application" @click="closeModal"><X :size="21" /></button></div><form @submit.prevent="save" @invalid.capture="tab = 'details'"><div class="dialog-tabs"><button type="button" :class="{ active: tab === 'details' }" @click="tab = 'details'">Overview</button><button v-if="draft.stage !== 'potential'" type="button" :class="{ active: tab === 'interviews' }" @click="tab = 'interviews'">Interviews <span>{{ draft.interviews.length }}</span></button></div><div class="dialog-body"><div v-show="tab === 'details'" class="form-grid"><div class="full"><div class="field-heading">Card color & star</div><CardPreferences :color="draft.color" :starred="draft.starred" :company="draft.company || 'application'" @change="Object.assign(draft, $event)" /></div><label>{{ draft.stage === 'potential' ? 'Opportunity name' : 'Company name' }} <span>*</span><input ref="companyInput" v-model="draft.company" required maxlength="150" placeholder="e.g. Linear"></label><label v-if="draft.stage !== 'potential'">Job title <span>*</span><input v-model="draft.title" required maxlength="200" placeholder="e.g. Product Designer"></label><label>Pipeline stage<select v-model="pipelineStage"><option v-for="stage in boardStages" :key="stage.id" :value="stage.id">{{ stage.name }}</option></select></label><label v-if="pipelineStage === 'ended'">Reason for ending<select v-model="draft.stage" required><option disabled value="ended">Choose an outcome</option><option v-for="outcome in endingOutcomes" :key="outcome.id" :value="outcome.id">{{ outcome.name }}</option></select></label><label>Employment type<select v-model="draft.employmentType"><option value="">Not specified</option><option v-for="type in employmentTypes" :key="type" :value="type">{{ type }}</option></select></label><template v-if="draft.stage !== 'potential'"><label>Applied on<input v-model="draft.date" type="date"></label><label>Company location<input v-model="draft.location" placeholder="City, state or country"></label><label>Work arrangement<select v-model="draft.workplace"><option>Remote</option><option>Onsite</option><option>Hybrid</option></select></label><label>Business / industry<input v-model="draft.business" placeholder="e.g. Design tools"></label><label>Salary range<input v-model="draft.salary" placeholder="e.g. $140k – $170k / year"></label></template><label class="full">{{ draft.stage === 'potential' ? 'Application link' : 'Job posting URL' }}<div class="url-field"><input v-model="draft.url" :required="draft.stage === 'potential'" type="url" placeholder="https://…"><a v-if="safeUrl(draft.url)" :href="safeUrl(draft.url)" target="_blank" rel="noopener noreferrer" aria-label="Open job posting"><ExternalLink :size="17" /></a></div></label><template v-if="draft.stage !== 'potential'"><fieldset class="full perks-field"><legend>Perks & benefits</legend><div class="perk-options"><label v-for="perk in [...new Set(['401k', 'PTO', 'Stocks', 'Maternity', 'Medical', ...draft.perks])]" :key="perk"><input v-model="draft.perks" type="checkbox" :value="perk">{{ perk }}</label></div><div class="inline-input"><input v-model="customPerk" placeholder="Add a custom perk" aria-label="Custom perk" @keydown.enter.prevent="addPerk"><button type="button" class="secondary" @click="addPerk"><Plus :size="16" /> Add</button></div></fieldset><div class="full"><div class="field-heading">Custom attributes<button type="button" class="text-button" @click="draft.attributes.push({name:'',value:''})"><Plus :size="14" /> Add field</button></div><div v-for="(attribute, index) in draft.attributes" :key="index" class="inline-input attribute"><input v-model="attribute.name" placeholder="Attribute name" aria-label="Attribute name"><input v-model="attribute.value" placeholder="Value" aria-label="Attribute value"><button type="button" class="icon-button" aria-label="Remove attribute" @click="draft.attributes.splice(index,1)"><X :size="16" /></button></div></div><label v-if="reasonLabels[draft.stage]" class="full">{{ reasonLabels[draft.stage] }}<textarea v-model="draft.reasons[draft.stage]" rows="3" placeholder="Capture what happened for your future self…"></textarea></label><label class="full">Notes<textarea v-model="draft.notes" rows="3" placeholder="What excites you? What would you like to follow up on?"></textarea></label></template><section v-if="store.applications.some(a => a.id === draft.id)" class="full timestamp-details"><h3>Activity</h3><dl><div><dt>Created</dt><dd>{{ timestampLabel(draft.createdAt) }}</dd></div><div><dt>Last updated</dt><dd>{{ timestampLabel(draft.updatedAt) }}</dd></div><div><dt>Entered current stage</dt><dd>{{ timestampLabel(draft.stageEnteredAt) }}</dd></div></dl><p v-if="!draft.createdAt">Older applications did not record timestamps. New edits and stage changes will be tracked.</p><ol v-if="draft.stageHistory.length"><li v-for="(entry, index) in draft.stageHistory" :key="index"><strong>{{ stages.find(s => s.id === entry.stage)?.name }}</strong><time :datetime="entry.enteredAt">{{ timestampLabel(entry.enteredAt) }}</time></li></ol></section></div>
            <div v-show="tab === 'interviews'"><div class="interviews-heading"><div><h3>Every conversation counts.</h3><p>Keep track of the people, the rounds, and how it felt.</p></div><button type="button" class="secondary" @click="addRound()"><Plus :size="15" /> Add round</button></div><div v-if="!draft.interviews.length" class="empty-state"><CalendarDays :size="32" /><p>No interviews yet. Add your first round above.</p></div><div v-for="(interview,index) in draft.interviews" :key="interview.id" class="interview-form"><div class="field-heading">Round {{ index + 1 }}<button type="button" class="icon-button" aria-label="Remove interview round" @click="draft.interviews.splice(index,1)"><Trash2 :size="15" /></button></div><div class="form-grid"><label>Interview stage<input v-model="interview.name" placeholder="e.g. Technical interview"></label><label>Interview date<input v-model="interview.date" type="date"></label><label class="full">Person interviewed with<input v-model="interview.person" placeholder="Name and role"></label><div class="full"><div class="field-heading">How did it go?</div><div class="stars"><button v-for="rating in 5" :key="rating" type="button" :aria-label="`Rate ${rating} out of 5 stars`" :aria-pressed="interview.rating === rating" @click="interview.rating = rating"><Star :size="25" :class="{ filled: rating <= interview.rating }" /></button><button v-if="interview.rating" type="button" class="text-button" @click="interview.rating = 0">Clear</button></div></div><label class="full">Interview notes<textarea v-model="interview.notes" rows="3" placeholder="Highlights, questions, and next steps…"></textarea></label></div></div></div>
          </div><div v-if="store.error" class="error-banner" role="alert">{{ store.error }}</div><div class="dialog-footer"><button v-if="store.applications.some(a => a.id === draft.id)" type="button" class="delete-link" @click="remove"><Trash2 :size="16" /> Delete</button><span v-else class="local-note"><ShieldCheck :size="14" /> Saved only on this browser</span><div><button type="button" class="secondary" @click="closeModal">Cancel</button><button class="primary" type="submit" @click="(!draft.company.trim() || (draft.stage !== 'potential' && !draft.title.trim())) && (tab = 'details')"><Check :size="16" /> Save application</button></div></div></form></section></div>
    <div v-if="notice" class="toast" role="status"><Check :size="17" />{{ notice }}<button class="icon-button" aria-label="Dismiss notification" @click="notice = ''"><X :size="15" /></button></div>
  </div>
</template>
